#include <cmath>
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <vector>
#include <omp.h>

// 18 outcomes: k in {0,1,2}, b in {0..5} -> d = 6*k + b
// Depths 0..8 -> total states = C(18+8, 8) = 1,562,275
// Non-terminal depths 0..7 -> C(18+7, 7) = 480,700

static const int NUM_OUTCOMES = 18;
static const int NUM_SEGMENTS = 6;
static const int MAX_DEPTH = 8;

static int layer_start[MAX_DEPTH + 2];
static std::vector<int32_t> child_table;   // size: nonterm * 18
static std::vector<int32_t> parent_node;   // size: total_states
static std::vector<int8_t>  added_outcome; // size: total_states
static bool initialized = false;

// Combinatorial helper: C(n, k)
static int64_t binom(int n, int k) {
    if (k < 0 || k > n) return 0;
    if (k == 0 || k == n) return 1;
    int64_t res = 1;
    if (k > n - k) k = n - k;
    for (int i = 1; i <= k; ++i) {
        res = res * (n - k + i) / i;
    }
    return res;
}

// Rank a sorted tuple d[0..t-1] in {0..17} into [0, C(17+t, t) - 1]
// Using standard multiset combinadic: map a_i = d_i + i (strictly increasing in 0..17+t-1)
// Lexicographical rank or colexicographical rank! Colex rank is super fast and clean:
// colex_rank(a_0 < a_1 < ... < a_{t-1}) = sum_{i=0}^{t-1} C(a_i, i + 1)
static inline int32_t colex_rank(const int* d, int t) {
    int32_t r = 0;
    for (int i = 0; i < t; ++i) {
        int a = d[i] + i;
        // C(a, i+1)
        int64_t c = 1;
        int k = i + 1;
        if (k > a) {
            c = 0;
        } else {
            if (k > a - k) k = a - k;
            for (int j = 1; j <= k; ++j) c = c * (a - k + j) / j;
        }
        r += (int32_t)c;
    }
    return r;
}

static void generate_layer(int t, int idx, int min_val, int* cur, std::vector<int>& all_tuples) {
    if (idx == t) {
        int32_t r = colex_rank(cur, t);
        for (int i = 0; i < t; ++i) {
            all_tuples[r * t + i] = cur[i];
        }
        return;
    }
    for (int v = min_val; v < NUM_OUTCOMES; ++v) {
        cur[idx] = v;
        generate_layer(t, idx + 1, v, cur, all_tuples);
    }
}

extern "C" {

void init_dp() {
    if (initialized) return;
    layer_start[0] = 0;
    for (int t = 0; t <= MAX_DEPTH; ++t) {
        int sz = (int)binom(NUM_OUTCOMES + t - 1, t);
        layer_start[t + 1] = layer_start[t] + sz;
    }
    int total_states = layer_start[MAX_DEPTH + 1];
    int nonterm_states = layer_start[MAX_DEPTH];

    child_table.resize((size_t)nonterm_states * NUM_OUTCOMES);
    parent_node.assign(total_states, -1);
    added_outcome.assign(total_states, -1);

    int cur[MAX_DEPTH + 1];
    int nxt[MAX_DEPTH + 1];

    for (int t = 0; t < MAX_DEPTH; ++t) {
        int sz = layer_start[t + 1] - layer_start[t];
        std::vector<int> tuples((size_t)sz * std::max(1, t));
        if (t > 0) {
            generate_layer(t, 0, 0, cur, tuples);
        }
        for (int r = 0; r < sz; ++r) {
            int u = layer_start[t] + r;
            const int* tup = (t > 0) ? &tuples[(size_t)r * t] : nullptr;
            for (int d = 0; d < NUM_OUTCOMES; ++d) {
                // Insert d into sorted tup[0..t-1]
                int pos = 0;
                while (pos < t && tup[pos] <= d) {
                    nxt[pos] = tup[pos];
                    ++pos;
                }
                nxt[pos] = d;
                for (int i = pos; i < t; ++i) {
                    nxt[i + 1] = tup[i];
                }
                int32_t child_r = colex_rank(nxt, t + 1);
                int32_t v = layer_start[t + 1] + child_r;
                child_table[(size_t)u * NUM_OUTCOMES + d] = v;
                if (parent_node[v] == -1) {
                    parent_node[v] = u;
                    added_outcome[v] = (int8_t)d;
                }
            }
        }
    }
    initialized = true;
}

int get_state_id(const int* outcomes, int t) {
    init_dp();
    if (t == 0) return 0;
    int sorted_d[MAX_DEPTH + 1];
    for (int i = 0; i < t; ++i) sorted_d[i] = outcomes[i];
    std::sort(sorted_d, sorted_d + t);
    return layer_start[t] + colex_rank(sorted_d, t);
}

// Solve exact DP for K priors given M posterior samples of P[m][18][6]
// P_samples: shape (M, 18, 6)
// priors: shape (K, 6)
// payoffs: shape (6,)
// check_cost: double (20.0)
// out_bayes_vals: shape (K,) -> V*(L_bar, prior_k)
// out_oracle_vals: shape (M, K) -> V*(L^(m), prior_k) (if compute_oracle != 0)
// out_root_actions: shape (K, 5) -> action values at root (decline=0, approve=1, check0=2, check1=3, check2=4) under L_bar
void solve_bayesian_dp(
    int M,
    const double* P_samples,
    int K,
    const double* priors,
    const double* payoffs,
    double check_cost,
    int compute_oracle,
    double* out_bayes_vals,
    double* out_oracle_vals,
    double* out_root_qvals
) {
    init_dp();
    int total_states = layer_start[MAX_DEPTH + 1];
    int nonterm_states = layer_start[MAX_DEPTH];

    std::vector<double> L_bar((size_t)total_states * NUM_SEGMENTS, 0.0);
    double inv_M = 1.0 / (double)M;

    #pragma omp parallel
    {
        std::vector<double> L_local((size_t)total_states * NUM_SEGMENTS);
        std::vector<double> L_sum_thread((size_t)total_states * NUM_SEGMENTS, 0.0);
        std::vector<double> W;
        if (compute_oracle) {
            W.resize((size_t)total_states * K);
        }

        #pragma omp for schedule(dynamic)
        for (int m = 0; m < M; ++m) {
            const double* Pm = P_samples + (size_t)m * (NUM_OUTCOMES * NUM_SEGMENTS);
            for (int s = 0; s < NUM_SEGMENTS; ++s) {
                L_local[s] = 1.0;
            }
            for (int u = 1; u < total_states; ++u) {
                int p = parent_node[u];
                int d = added_outcome[u];
                const double* Lp = &L_local[(size_t)p * NUM_SEGMENTS];
                const double* Pd = &Pm[d * NUM_SEGMENTS];
                double* Lu = &L_local[(size_t)u * NUM_SEGMENTS];
                for (int s = 0; s < NUM_SEGMENTS; ++s) {
                    Lu[s] = Lp[s] * Pd[s];
                }
            }
            for (size_t i = 0; i < L_local.size(); ++i) {
                L_sum_thread[i] += L_local[i];
            }

            if (compute_oracle) {
                // Terminal layer t = 8
                for (int u = nonterm_states; u < total_states; ++u) {
                    const double* Lu = &L_local[(size_t)u * NUM_SEGMENTS];
                    double* Wu = &W[(size_t)u * K];
                    for (int k = 0; k < K; ++k) {
                        const double* pk = &priors[k * NUM_SEGMENTS];
                        double A = 0.0;
                        for (int s = 0; s < NUM_SEGMENTS; ++s) {
                            A += pk[s] * payoffs[s] * Lu[s];
                        }
                        Wu[k] = (A > 0.0) ? A : 0.0;
                    }
                }
                // Backward induction t = 7 .. 0
                for (int u = nonterm_states - 1; u >= 0; --u) {
                    const double* Lu = &L_local[(size_t)u * NUM_SEGMENTS];
                    const int32_t* ch = &child_table[(size_t)u * NUM_OUTCOMES];
                    double* Wu = &W[(size_t)u * K];
                    for (int k = 0; k < K; ++k) {
                        const double* pk = &priors[k * NUM_SEGMENTS];
                        double Z = 0.0;
                        double A = 0.0;
                        for (int s = 0; s < NUM_SEGMENTS; ++s) {
                            double q = pk[s] * Lu[s];
                            Z += q;
                            A += q * payoffs[s];
                        }
                        double best = (A > 0.0) ? A : 0.0;
                        for (int c = 0; c < 3; ++c) {
                            double sum_w = -check_cost * Z;
                            for (int b = 0; b < 6; ++b) {
                                sum_w += W[(size_t)ch[c * 6 + b] * K + k];
                            }
                            if (sum_w > best) best = sum_w;
                        }
                        Wu[k] = best;
                    }
                }
                for (int k = 0; k < K; ++k) {
                    out_oracle_vals[m * K + k] = W[k];
                }
            }
        }

        #pragma omp critical
        {
            for (size_t i = 0; i < L_bar.size(); ++i) {
                L_bar[i] += L_sum_thread[i] * inv_M;
            }
        }
    }

    // Now solve backward induction on L_bar for all K priors
    std::vector<double> W_bar((size_t)total_states * K);
    #pragma omp parallel for schedule(static)
    for (int u = nonterm_states; u < total_states; ++u) {
        const double* Lu = &L_bar[(size_t)u * NUM_SEGMENTS];
        double* Wu = &W_bar[(size_t)u * K];
        for (int k = 0; k < K; ++k) {
            const double* pk = &priors[k * NUM_SEGMENTS];
            double A = 0.0;
            for (int s = 0; s < NUM_SEGMENTS; ++s) {
                A += pk[s] * payoffs[s] * Lu[s];
            }
            Wu[k] = (A > 0.0) ? A : 0.0;
        }
    }

    for (int t = MAX_DEPTH - 1; t >= 0; --t) {
        int u_start = layer_start[t];
        int u_end = layer_start[t + 1];
        #pragma omp parallel for schedule(static)
        for (int u = u_start; u < u_end; ++u) {
            const double* Lu = &L_bar[(size_t)u * NUM_SEGMENTS];
            const int32_t* ch = &child_table[(size_t)u * NUM_OUTCOMES];
            double* Wu = &W_bar[(size_t)u * K];
            for (int k = 0; k < K; ++k) {
                const double* pk = &priors[k * NUM_SEGMENTS];
                double Z = 0.0;
                double A = 0.0;
                for (int s = 0; s < NUM_SEGMENTS; ++s) {
                    double q = pk[s] * Lu[s];
                    Z += q;
                    A += q * payoffs[s];
                }
                double best = (A > 0.0) ? A : 0.0;
                for (int c = 0; c < 3; ++c) {
                    double sum_w = -check_cost * Z;
                    for (int b = 0; b < 6; ++b) {
                        sum_w += W_bar[(size_t)ch[c * 6 + b] * K + k];
                    }
                    if (sum_w > best) best = sum_w;
                }
                Wu[k] = best;
                if (u == 0 && out_root_qvals != nullptr) {
                    out_root_qvals[k * 5 + 0] = 0.0;
                    out_root_qvals[k * 5 + 1] = A;
                    for (int c = 0; c < 3; ++c) {
                        double sum_w = -check_cost * Z;
                        for (int b = 0; b < 6; ++b) {
                            sum_w += W_bar[(size_t)ch[c * 6 + b] * K + k];
                        }
                        out_root_qvals[k * 5 + 2 + c] = sum_w;
                    }
                }
            }
        }
    }

    for (int k = 0; k < K; ++k) {
        out_bayes_vals[k] = W_bar[k];
    }
}

// Query Q-values at ANY specific state_id for ONE applicant (prior[6]), given M posterior samples P_samples
// Returns conditional expected values (divided by Z(state_id)) for [decline, approve, bureau, income, bank]
void query_state_qvals(
    int M,
    const double* P_samples,
    const double* prior,
    const double* payoffs,
    double check_cost,
    int state_id,
    int depth,
    double* out_qvals,
    double* out_posterior
) {
    init_dp();
    int total_states = layer_start[MAX_DEPTH + 1];
    int nonterm_states = layer_start[MAX_DEPTH];

    std::vector<double> L_bar((size_t)total_states * NUM_SEGMENTS, 0.0);
    double inv_M = 1.0 / (double)M;

    #pragma omp parallel
    {
        std::vector<double> L_local((size_t)total_states * NUM_SEGMENTS);
        std::vector<double> L_sum_thread((size_t)total_states * NUM_SEGMENTS, 0.0);

        #pragma omp for schedule(static)
        for (int m = 0; m < M; ++m) {
            const double* Pm = P_samples + (size_t)m * (NUM_OUTCOMES * NUM_SEGMENTS);
            for (int s = 0; s < NUM_SEGMENTS; ++s) L_local[s] = 1.0;
            for (int u = 1; u < total_states; ++u) {
                int p = parent_node[u];
                int d = added_outcome[u];
                const double* Lp = &L_local[(size_t)p * NUM_SEGMENTS];
                const double* Pd = &Pm[d * NUM_SEGMENTS];
                double* Lu = &L_local[(size_t)u * NUM_SEGMENTS];
                for (int s = 0; s < NUM_SEGMENTS; ++s) Lu[s] = Lp[s] * Pd[s];
            }
            for (size_t i = 0; i < L_local.size(); ++i) L_sum_thread[i] += L_local[i];
        }
        #pragma omp critical
        {
            for (size_t i = 0; i < L_bar.size(); ++i) L_bar[i] += L_sum_thread[i] * inv_M;
        }
    }

    std::vector<double> W_bar(total_states, 0.0);
    #pragma omp parallel for schedule(static)
    for (int u = nonterm_states; u < total_states; ++u) {
        const double* Lu = &L_bar[(size_t)u * NUM_SEGMENTS];
        double A = 0.0;
        for (int s = 0; s < NUM_SEGMENTS; ++s) A += prior[s] * payoffs[s] * Lu[s];
        W_bar[u] = (A > 0.0) ? A : 0.0;
    }

    for (int t = MAX_DEPTH - 1; t >= depth; --t) {
        int u_start = layer_start[t];
        int u_end = layer_start[t + 1];
        #pragma omp parallel for schedule(static)
        for (int u = u_start; u < u_end; ++u) {
            const double* Lu = &L_bar[(size_t)u * NUM_SEGMENTS];
            const int32_t* ch = &child_table[(size_t)u * NUM_OUTCOMES];
            double Z = 0.0, A = 0.0;
            for (int s = 0; s < NUM_SEGMENTS; ++s) {
                double q = prior[s] * Lu[s];
                Z += q;
                A += q * payoffs[s];
            }
            double best = (A > 0.0) ? A : 0.0;
            for (int c = 0; c < 3; ++c) {
                double sum_w = -check_cost * Z;
                for (int b = 0; b < 6; ++b) sum_w += W_bar[ch[c * 6 + b]];
                if (sum_w > best) best = sum_w;
            }
            W_bar[u] = best;
        }
    }

    const double* Lu = &L_bar[(size_t)state_id * NUM_SEGMENTS];
    double Z = 0.0, A = 0.0;
    for (int s = 0; s < NUM_SEGMENTS; ++s) {
        double q = prior[s] * Lu[s];
        out_posterior[s] = q;
        Z += q;
        A += q * payoffs[s];
    }
    if (Z > 0.0) {
        for (int s = 0; s < NUM_SEGMENTS; ++s) out_posterior[s] /= Z;
    }
    out_qvals[0] = 0.0;
    out_qvals[1] = (Z > 0.0) ? (A / Z) : -1e9;
    if (depth < MAX_DEPTH && Z > 0.0) {
        const int32_t* ch = &child_table[(size_t)state_id * NUM_OUTCOMES];
        for (int c = 0; c < 3; ++c) {
            double sum_w = -check_cost * Z;
            for (int b = 0; b < 6; ++b) sum_w += W_bar[ch[c * 6 + b]];
            out_qvals[2 + c] = sum_w / Z;
        }
    } else {
        out_qvals[2] = -1e9;
        out_qvals[3] = -1e9;
        out_qvals[4] = -1e9;
    }
}

}

#include <cmath>
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <vector>
#include <omp.h>

static const int NUM_OUTCOMES = 18;
static const int NUM_BANDS = 6;
static const int NUM_SEGMENTS = 6;
static const int MAX_DEPTH = 8;

static int layer_start[MAX_DEPTH + 2];
static int sub_layer_start[MAX_DEPTH + 2]; // for 6-band single-check multisets (total 3003)

static std::vector<int32_t> child_table;      // nonterm * 18
static std::vector<int32_t> parent_node;      // total_states
static std::vector<int8_t>  added_outcome;    // total_states
static std::vector<int16_t> sub_ids;          // total_states * 3 (sub_id in 0..3002 for each check)

static std::vector<int16_t> sub_parent;       // 3003
static std::vector<int8_t>  sub_added_band;   // 3003
static bool initialized = false;

static int64_t binom(int n, int k) {
    if (k < 0 || k > n) return 0;
    if (k == 0 || k == n) return 1;
    int64_t res = 1;
    if (k > n - k) k = n - k;
    for (int i = 1; i <= k; ++i) res = res * (n - k + i) / i;
    return res;
}

static inline int32_t colex_rank(const int* d, int t) {
    int32_t r = 0;
    for (int i = 0; i < t; ++i) {
        int a = d[i] + i;
        int64_t c = 1;
        int k = i + 1;
        if (k > a) {
            c = 0;
        } else {
            if (k > a - k) k = a - k;
            for (int j = 1; j <= k; ++j) c = c * (a - k + j) / j;
        }
        r += (int32_t)c;
    }
    return r;
}

static void generate_layer(int num_vals, int t, int idx, int min_val, int* cur, std::vector<int>& all_tuples) {
    if (idx == t) {
        int32_t r = colex_rank(cur, t);
        for (int i = 0; i < t; ++i) all_tuples[(size_t)r * t + i] = cur[i];
        return;
    }
    for (int v = min_val; v < num_vals; ++v) {
        cur[idx] = v;
        generate_layer(num_vals, t, idx + 1, v, cur, all_tuples);
    }
}

extern "C" {

void init_dp() {
    if (initialized) return;

    // 1. Single-check 6-band multiset table (3003 states)
    sub_layer_start[0] = 0;
    for (int t = 0; t <= MAX_DEPTH; ++t) {
        int sz = (int)binom(NUM_BANDS + t - 1, t);
        sub_layer_start[t + 1] = sub_layer_start[t] + sz;
    }
    int total_sub = sub_layer_start[MAX_DEPTH + 1]; // 3003
    sub_parent.assign(total_sub, -1);
    sub_added_band.assign(total_sub, -1);
    {
        int cur[MAX_DEPTH + 1], nxt[MAX_DEPTH + 1];
        for (int t = 0; t < MAX_DEPTH; ++t) {
            int sz = sub_layer_start[t + 1] - sub_layer_start[t];
            std::vector<int> tuples((size_t)sz * std::max(1, t));
            if (t > 0) generate_layer(NUM_BANDS, t, 0, 0, cur, tuples);
            for (int r = 0; r < sz; ++r) {
                int u = sub_layer_start[t] + r;
                const int* tup = (t > 0) ? &tuples[(size_t)r * t] : nullptr;
                for (int b = 0; b < NUM_BANDS; ++b) {
                    int pos = 0;
                    while (pos < t && tup[pos] <= b) { nxt[pos] = tup[pos]; ++pos; }
                    nxt[pos] = b;
                    for (int i = pos; i < t; ++i) nxt[i + 1] = tup[i];
                    int v = sub_layer_start[t + 1] + colex_rank(nxt, t + 1);
                    if (sub_parent[v] == -1) {
                        sub_parent[v] = (int16_t)u;
                        sub_added_band[v] = (int8_t)b;
                    }
                }
            }
        }
    }

    // 2. Global 18-outcome multiset table (1,562,275 states)
    layer_start[0] = 0;
    for (int t = 0; t <= MAX_DEPTH; ++t) {
        int sz = (int)binom(NUM_OUTCOMES + t - 1, t);
        layer_start[t + 1] = layer_start[t] + sz;
    }
    int total_states = layer_start[MAX_DEPTH + 1];
    int nonterm_states = layer_start[MAX_DEPTH];

    child_table.resize((size_t)nonterm_states * NUM_OUTCOMES);
    parent_node.assign(total_states, -1);
    added_outcome.assign(total_states, -1);
    sub_ids.resize((size_t)total_states * 3);

    int cur[MAX_DEPTH + 1], nxt[MAX_DEPTH + 1];
    int b_sub[3][MAX_DEPTH + 1], len_sub[3];

    for (int t = 0; t <= MAX_DEPTH; ++t) {
        int sz = layer_start[t + 1] - layer_start[t];
        std::vector<int> tuples((size_t)sz * std::max(1, t));
        if (t > 0) generate_layer(NUM_OUTCOMES, t, 0, 0, cur, tuples);
        for (int r = 0; r < sz; ++r) {
            int u = layer_start[t] + r;
            const int* tup = (t > 0) ? &tuples[(size_t)r * t] : nullptr;

            // Compute sub_ids[u * 3 + 0..2]
            len_sub[0] = len_sub[1] = len_sub[2] = 0;
            for (int i = 0; i < t; ++i) {
                int d = tup[i];
                int c = d / 6;
                int b = d % 6;
                b_sub[c][len_sub[c]++] = b; // already sorted!
            }
            for (int c = 0; c < 3; ++c) {
                int lt = len_sub[c];
                int sid = (lt == 0) ? 0 : (sub_layer_start[lt] + colex_rank(b_sub[c], lt));
                sub_ids[(size_t)u * 3 + c] = (int16_t)sid;
            }

            if (t < MAX_DEPTH) {
                for (int d = 0; d < NUM_OUTCOMES; ++d) {
                    int pos = 0;
                    while (pos < t && tup[pos] <= d) { nxt[pos] = tup[pos]; ++pos; }
                    nxt[pos] = d;
                    for (int i = pos; i < t; ++i) nxt[i + 1] = tup[i];
                    int32_t v = layer_start[t + 1] + colex_rank(nxt, t + 1);
                    child_table[(size_t)u * NUM_OUTCOMES + d] = v;
                    if (parent_node[v] == -1) {
                        parent_node[v] = u;
                        added_outcome[v] = (int8_t)d;
                    }
                }
            }
        }
    }
    initialized = true;
}

int get_state_id(const int* outcomes, int t) {
    init_dp();
    if (t == 0) return 0;
    int sorted_d[MAX_DEPTH + 1];
    for (int i = 0; i < t; ++i) sorted_d[i] = outcomes[i];
    std::sort(sorted_d, sorted_d + t);
    return layer_start[t] + colex_rank(sorted_d, t);
}

// Helper: compute L_sub[3003 * 6] for a single check given weighted samples P_k[M_k][6][6] and weights w[M_k] (sum w = 1)
static void compute_single_check_Lbar(int M_k, const double* P_k, const double* weights, double* L_sub_out) {
    int total_sub = sub_layer_start[MAX_DEPTH + 1]; // 3003
    std::memset(L_sub_out, 0, (size_t)total_sub * NUM_SEGMENTS * sizeof(double));
    std::vector<double> L_loc((size_t)total_sub * NUM_SEGMENTS);

    for (int m = 0; m < M_k; ++m) {
        double wm = (weights != nullptr) ? weights[m] : (1.0 / (double)M_k);
        if (wm <= 0.0) continue;
        const double* Pm = P_k + (size_t)m * (NUM_BANDS * NUM_SEGMENTS);
        for (int s = 0; s < NUM_SEGMENTS; ++s) L_loc[s] = 1.0;
        for (int u = 1; u < total_sub; ++u) {
            int p = sub_parent[u];
            int b = sub_added_band[u];
            const double* Lp = &L_loc[(size_t)p * NUM_SEGMENTS];
            const double* Pb = &Pm[b * NUM_SEGMENTS];
            double* Lu = &L_loc[(size_t)u * NUM_SEGMENTS];
            for (int s = 0; s < NUM_SEGMENTS; ++s) Lu[s] = Lp[s] * Pb[s];
        }
        for (size_t i = 0; i < L_loc.size(); ++i) {
            L_sub_out[i] += wm * L_loc[i];
        }
    }
}

// Ultra-fast Factored Exact Bayesian DP (~0.07s regardless of M0, M1, M2!)
void solve_factored_dp(
    int M0, const double* P0, const double* w0,
    int M1, const double* P1, const double* w1,
    int M2, const double* P2, const double* w2,
    int K, const double* priors, const double* payoffs, double check_cost,
    double* out_bayes_vals,
    double* out_root_qvals
) {
    init_dp();
    int total_sub = sub_layer_start[MAX_DEPTH + 1];
    int total_states = layer_start[MAX_DEPTH + 1];
    int nonterm_states = layer_start[MAX_DEPTH];

    std::vector<double> L0((size_t)total_sub * NUM_SEGMENTS);
    std::vector<double> L1((size_t)total_sub * NUM_SEGMENTS);
    std::vector<double> L2((size_t)total_sub * NUM_SEGMENTS);
    compute_single_check_Lbar(M0, P0, w0, L0.data());
    compute_single_check_Lbar(M1, P1, w1, L1.data());
    compute_single_check_Lbar(M2, P2, w2, L2.data());

    std::vector<double> W_bar((size_t)total_states * K);

    // Terminal layer t = 8: compute L_bar on the fly without even allocating 75MB L_bar array!!
    #pragma omp parallel for schedule(static)
    for (int u = nonterm_states; u < total_states; ++u) {
        const int16_t* sids = &sub_ids[(size_t)u * 3];
        const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
        const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
        const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
        double Lu[NUM_SEGMENTS];
        for (int s = 0; s < NUM_SEGMENTS; ++s) Lu[s] = l0[s] * l1[s] * l2[s];

        double* Wu = &W_bar[(size_t)u * K];
        for (int k = 0; k < K; ++k) {
            const double* pk = &priors[k * NUM_SEGMENTS];
            double A = 0.0;
            for (int s = 0; s < NUM_SEGMENTS; ++s) A += pk[s] * payoffs[s] * Lu[s];
            Wu[k] = (A > 0.0) ? A : 0.0;
        }
    }

    for (int t = MAX_DEPTH - 1; t >= 0; --t) {
        int u_start = layer_start[t];
        int u_end = layer_start[t + 1];
        #pragma omp parallel for schedule(static)
        for (int u = u_start; u < u_end; ++u) {
            const int16_t* sids = &sub_ids[(size_t)u * 3];
            const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
            const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
            const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
            double Lu[NUM_SEGMENTS];
            for (int s = 0; s < NUM_SEGMENTS; ++s) Lu[s] = l0[s] * l1[s] * l2[s];

            const int32_t* ch = &child_table[(size_t)u * NUM_OUTCOMES];
            double* Wu = &W_bar[(size_t)u * K];
            for (int k = 0; k < K; ++k) {
                const double* pk = &priors[k * NUM_SEGMENTS];
                double Z = 0.0, A = 0.0;
                for (int s = 0; s < NUM_SEGMENTS; ++s) {
                    double q = pk[s] * Lu[s];
                    Z += q;
                    A += q * payoffs[s];
                }
                double best = (A > 0.0) ? A : 0.0;
                for (int c = 0; c < 3; ++c) {
                    double sum_w = -check_cost * Z;
                    for (int b = 0; b < 6; ++b) sum_w += W_bar[(size_t)ch[c * 6 + b] * K + k];
                    if (sum_w > best) best = sum_w;
                }
                Wu[k] = best;
                if (u == 0 && out_root_qvals != nullptr) {
                    out_root_qvals[k * 5 + 0] = 0.0;
                    out_root_qvals[k * 5 + 1] = A;
                    for (int c = 0; c < 3; ++c) {
                        double sum_w = -check_cost * Z;
                        for (int b = 0; b < 6; ++b) sum_w += W_bar[(size_t)ch[c * 6 + b] * K + k];
                        out_root_qvals[k * 5 + 2 + c] = sum_w;
                    }
                }
            }
        }
    }

    for (int k = 0; k < K; ++k) out_bayes_vals[k] = W_bar[k];
}

// Compute oracle values V*(P^(m), priors) for M joint samples P_samples[M][18][6] in parallel
void compute_oracle_batch(
    int M, const double* P_samples,
    int K, const double* priors, const double* payoffs, double check_cost,
    double* out_oracle_vals
) {
    init_dp();
    int total_sub = sub_layer_start[MAX_DEPTH + 1];
    int total_states = layer_start[MAX_DEPTH + 1];
    int nonterm_states = layer_start[MAX_DEPTH];

    #pragma omp parallel
    {
        std::vector<double> L0((size_t)total_sub * NUM_SEGMENTS);
        std::vector<double> L1((size_t)total_sub * NUM_SEGMENTS);
        std::vector<double> L2((size_t)total_sub * NUM_SEGMENTS);
        std::vector<double> W((size_t)total_states * K);

        #pragma omp for schedule(dynamic)
        for (int m = 0; m < M; ++m) {
            const double* Pm = P_samples + (size_t)m * (NUM_OUTCOMES * NUM_SEGMENTS);
            compute_single_check_Lbar(1, Pm + 0 * 36, nullptr, L0.data());
            compute_single_check_Lbar(1, Pm + 1 * 36, nullptr, L1.data());
            compute_single_check_Lbar(1, Pm + 2 * 36, nullptr, L2.data());

            for (int u = nonterm_states; u < total_states; ++u) {
                const int16_t* sids = &sub_ids[(size_t)u * 3];
                const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
                const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
                const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
                double Lu[NUM_SEGMENTS];
                for (int s = 0; s < NUM_SEGMENTS; ++s) Lu[s] = l0[s] * l1[s] * l2[s];
                double* Wu = &W[(size_t)u * K];
                for (int k = 0; k < K; ++k) {
                    const double* pk = &priors[k * NUM_SEGMENTS];
                    double A = 0.0;
                    for (int s = 0; s < NUM_SEGMENTS; ++s) A += pk[s] * payoffs[s] * Lu[s];
                    Wu[k] = (A > 0.0) ? A : 0.0;
                }
            }
            for (int u = nonterm_states - 1; u >= 0; --u) {
                const int16_t* sids = &sub_ids[(size_t)u * 3];
                const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
                const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
                const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
                double Lu[NUM_SEGMENTS];
                for (int s = 0; s < NUM_SEGMENTS; ++s) Lu[s] = l0[s] * l1[s] * l2[s];
                const int32_t* ch = &child_table[(size_t)u * NUM_OUTCOMES];
                double* Wu = &W[(size_t)u * K];
                for (int k = 0; k < K; ++k) {
                    const double* pk = &priors[k * NUM_SEGMENTS];
                    double Z = 0.0, A = 0.0;
                    for (int s = 0; s < NUM_SEGMENTS; ++s) {
                        double q = pk[s] * Lu[s];
                        Z += q;
                        A += q * payoffs[s];
                    }
                    double best = (A > 0.0) ? A : 0.0;
                    for (int c = 0; c < 3; ++c) {
                        double sum_w = -check_cost * Z;
                        for (int b = 0; b < 6; ++b) sum_w += W[(size_t)ch[c * 6 + b] * K + k];
                        if (sum_w > best) best = sum_w;
                    }
                    Wu[k] = best;
                }
            }
            for (int k = 0; k < K; ++k) out_oracle_vals[m * K + k] = W[k];
        }
    }
}

// Ultra-fast single-applicant state query at ANY state_id (~0.015s for any M0, M1, M2!)
void query_factored_state_qvals(
    int M0, const double* P0, const double* w0,
    int M1, const double* P1, const double* w1,
    int M2, const double* P2, const double* w2,
    const double* prior, const double* payoffs, double check_cost,
    int state_id, int depth,
    double* out_qvals, double* out_posterior
) {
    init_dp();
    int total_sub = sub_layer_start[MAX_DEPTH + 1];
    int total_states = layer_start[MAX_DEPTH + 1];
    int nonterm_states = layer_start[MAX_DEPTH];

    std::vector<double> L0((size_t)total_sub * NUM_SEGMENTS);
    std::vector<double> L1((size_t)total_sub * NUM_SEGMENTS);
    std::vector<double> L2((size_t)total_sub * NUM_SEGMENTS);
    compute_single_check_Lbar(M0, P0, w0, L0.data());
    compute_single_check_Lbar(M1, P1, w1, L1.data());
    compute_single_check_Lbar(M2, P2, w2, L2.data());

    std::vector<double> W_bar(total_states, 0.0);
    #pragma omp parallel for schedule(static)
    for (int u = nonterm_states; u < total_states; ++u) {
        const int16_t* sids = &sub_ids[(size_t)u * 3];
        const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
        const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
        const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
        double A = 0.0;
        for (int s = 0; s < NUM_SEGMENTS; ++s) {
            A += prior[s] * payoffs[s] * (l0[s] * l1[s] * l2[s]);
        }
        W_bar[u] = (A > 0.0) ? A : 0.0;
    }

    for (int t = MAX_DEPTH - 1; t >= depth; --t) {
        int u_start = layer_start[t];
        int u_end = layer_start[t + 1];
        #pragma omp parallel for schedule(static)
        for (int u = u_start; u < u_end; ++u) {
            const int16_t* sids = &sub_ids[(size_t)u * 3];
            const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
            const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
            const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
            const int32_t* ch = &child_table[(size_t)u * NUM_OUTCOMES];
            double Z = 0.0, A = 0.0;
            for (int s = 0; s < NUM_SEGMENTS; ++s) {
                double q = prior[s] * (l0[s] * l1[s] * l2[s]);
                Z += q;
                A += q * payoffs[s];
            }
            double best = (A > 0.0) ? A : 0.0;
            for (int c = 0; c < 3; ++c) {
                double sum_w = -check_cost * Z;
                for (int b = 0; b < 6; ++b) sum_w += W_bar[ch[c * 6 + b]];
                if (sum_w > best) best = sum_w;
            }
            W_bar[u] = best;
        }
    }

    const int16_t* sids = &sub_ids[(size_t)state_id * 3];
    const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
    const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
    const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
    double Z = 0.0, A = 0.0;
    for (int s = 0; s < NUM_SEGMENTS; ++s) {
        double q = prior[s] * (l0[s] * l1[s] * l2[s]);
        out_posterior[s] = q;
        Z += q;
        A += q * payoffs[s];
    }
    if (Z > 0.0) {
        for (int s = 0; s < NUM_SEGMENTS; ++s) out_posterior[s] /= Z;
    }
    out_qvals[0] = 0.0;
    out_qvals[1] = (Z > 0.0) ? (A / Z) : -1e9;
    if (depth < MAX_DEPTH && Z > 0.0) {
        const int32_t* ch = &child_table[(size_t)state_id * NUM_OUTCOMES];
        for (int c = 0; c < 3; ++c) {
            double sum_w = -check_cost * Z;
            for (int b = 0; b < 6; ++b) sum_w += W_bar[ch[c * 6 + b]];
            out_qvals[2 + c] = sum_w / Z;
        }
    } else {
        out_qvals[2] = out_qvals[3] = out_qvals[4] = -1e9;
    }
}

}

