// Batch reweighted factored DP across B tasks in parallel across all OpenMP cores!
void solve_factored_reweighted_batch(
    int M,
    const double* P0, const double* P1, const double* P2,
    int B,
    const int* target_chk,     // shape (B,) in {0, 1, 2}
    const double* W_tasks,     // shape (B, M)
    int K, const double* priors, const double* payoffs, double check_cost,
    double* out_totals         // shape (B,)
) {
    init_dp();
