    int total_states = layer_start[MAX_DEPTH + 1];
    int nonterm_states = layer_start[MAX_DEPTH];

    std::vector<double> L0_base((size_t)total_sub * NUM_SEGMENTS);
    std::vector<double> L1_base((size_t)total_sub * NUM_SEGMENTS);
    std::vector<double> L2_base((size_t)total_sub * NUM_SEGMENTS);
    compute_single_check_Lbar(M, P0, nullptr, L0_base.data());
    compute_single_check_Lbar(M, P1, nullptr, L1_base.data());
    compute_single_check_Lbar(M, P2, nullptr, L2_base.data());

    #pragma omp parallel
    {
        std::vector<double> L_mod((size_t)total_sub * NUM_SEGMENTS);
        std::vector<double> W((size_t)total_states * K);

        #pragma omp for schedule(dynamic)
        for (int b_idx = 0; b_idx < B; ++b_idx) {
            int tc = target_chk[b_idx];
            const double* wb = W_tasks + (size_t)b_idx * M;
            const double* P_tc = (tc == 0) ? P0 : ((tc == 1) ? P1 : P2);
            compute_single_check_Lbar(M, P_tc, wb, L_mod.data());

            const double* L0 = (tc == 0) ? L_mod.data() : L0_base.data();
            const double* L1 = (tc == 1) ? L_mod.data() : L1_base.data();
            const double* L2 = (tc == 2) ? L_mod.data() : L2_base.data();

            for (int u = nonterm_states; u < total_states; ++u) {
                const int16_t* sids = &sub_ids[(size_t)u * 3];
                const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
                const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
                const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
                double Lu[NUM_SEGMENTS];
                for (int s = 0; s < NUM_SEGMENTS; ++s) Lu[s] = l0[s] * l1[s] * l2[s];
                double* Wu = &W[(size_t)u * K];
                for (int k = 0; k < K; ++k) {
                    const double* pk = &priors[k * NUM_SEGMENTS];
                    double A = 0.0;
                    for (int s = 0; s < NUM_SEGMENTS; ++s) A += pk[s] * payoffs[s] * Lu[s];
                    Wu[k] = (A > 0.0) ? A : 0.0;
                }
            }
            for (int u = nonterm_states - 1; u >= 0; --u) {
                const int16_t* sids = &sub_ids[(size_t)u * 3];
                const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
                const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
                const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
                double Lu[NUM_SEGMENTS];
                for (int s = 0; s < NUM_SEGMENTS; ++s) Lu[s] = l0[s] * l1[s] * l2[s];
                const int32_t* ch = &child_table[(size_t)u * NUM_OUTCOMES];
                double* Wu = &W[(size_t)u * K];
                for (int k = 0; k < K; ++k) {
                    const double* pk = &priors[k * NUM_SEGMENTS];
                    double Z = 0.0, A = 0.0;
                    for (int s = 0; s < NUM_SEGMENTS; ++s) {
                        double q = pk[s] * Lu[s];
                        Z += q;
                        A += q * payoffs[s];
                    }
                    double best = (A > 0.0) ? A : 0.0;
                    for (int c = 0; c < 3; ++c) {
                        double sum_w = -check_cost * Z;
                        for (int b = 0; b < 6; ++b) sum_w += W[(size_t)ch[c * 6 + b] * K + k];
                        if (sum_w > best) best = sum_w;
                    }
                    Wu[k] = best;
                }
            }
            double tot = 0.0;
            for (int k = 0; k < K; ++k) tot += W[k];
            out_totals[b_idx] = tot;
        }
    }
}

