// Compute single-segment L_sub column s (3003 doubles) given N_q quadrature points P_seg[N_q, 6] and weights w_q[N_q]
void compute_segment_Lbar_quad(int s_unused, int N_q, const double* P_seg, const double* w_q, double* out_col_3003) {
    init_dp();
    int total_sub = sub_layer_start[MAX_DEPTH + 1];
    std::memset(out_col_3003, 0, (size_t)total_sub * sizeof(double));
    std::vector<double> L_loc(total_sub);
    for (int m = 0; m < N_q; ++m) {
        double wm = w_q[m];
        if (wm <= 1e-15) continue;
        const double* pb = P_seg + (size_t)m * NUM_BANDS;
        L_loc[0] = 1.0;
        for (int u = 1; u < total_sub; ++u) {
            L_loc[u] = L_loc[sub_parent[u]] * pb[sub_added_band[u]];
        }
        for (int u = 0; u < total_sub; ++u) {
            out_col_3003[u] += wm * L_loc[u];
        }
    }
}

// Exact 3-check DP from precomputed exact quadrature tables L0, L1, L2 of shape (3003, 6)
void solve_dp_from_Lsub(
    const double* L0, const double* L1, const double* L2,
    int K, const double* priors, const double* payoffs, double check_cost,
    double* out_bayes_vals, double* out_root_qvals
) {
    init_dp();
    int total_states = layer_start[MAX_DEPTH + 1];
    int nonterm_states = layer_start[MAX_DEPTH];

    static std::vector<double> W_bar;
    if (W_bar.size() < (size_t)total_states * K) W_bar.resize((size_t)total_states * K);

    #pragma omp parallel for schedule(static)
    for (int u = nonterm_states; u < total_states; ++u) {
        const int16_t* sids = &sub_ids[(size_t)u * 3];
        const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
        const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
        const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
        double Lu[NUM_SEGMENTS];
        for (int s = 0; s < NUM_SEGMENTS; ++s) Lu[s] = l0[s] * l1[s] * l2[s];
        double* Wu = &W_bar[(size_t)u * K];
        for (int k = 0; k < K; ++k) {
            const double* pk = &priors[k * NUM_SEGMENTS];
            double A = 0.0;
            for (int s = 0; s < NUM_SEGMENTS; ++s) A += pk[s] * payoffs[s] * Lu[s];
            Wu[k] = (A > 0.0) ? A : 0.0;
        }
    }

    for (int t = MAX_DEPTH - 1; t >= 0; --t) {
        int u_start = layer_start[t];
        int u_end = layer_start[t + 1];
        #pragma omp parallel for schedule(static)
        for (int u = u_start; u < u_end; ++u) {
            const int16_t* sids = &sub_ids[(size_t)u * 3];
            const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
            const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
            const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
            double Lu[NUM_SEGMENTS];
            for (int s = 0; s < NUM_SEGMENTS; ++s) Lu[s] = l0[s] * l1[s] * l2[s];
            const int32_t* ch = &child_table[(size_t)u * NUM_OUTCOMES];
            double* Wu = &W_bar[(size_t)u * K];
            for (int k = 0; k < K; ++k) {
                const double* pk = &priors[k * NUM_SEGMENTS];
                double Z = 0.0, A = 0.0;
                for (int s = 0; s < NUM_SEGMENTS; ++s) {
                    double q = pk[s] * Lu[s];
                    Z += q;
                    A += q * payoffs[s];
                }
                double best = (A > 0.0) ? A : 0.0;
                for (int c = 0; c < 3; ++c) {
                    double sum_w = -check_cost * Z;
                    for (int b = 0; b < 6; ++b) sum_w += W_bar[(size_t)ch[c * 6 + b] * K + k];
                    if (sum_w > best) best = sum_w;
                }
                Wu[k] = best;
                if (u == 0 && out_root_qvals != nullptr) {
                    out_root_qvals[k * 5 + 0] = 0.0;
                    out_root_qvals[k * 5 + 1] = A;
                    for (int c = 0; c < 3; ++c) {
                        double sum_w = -check_cost * Z;
                        for (int b = 0; b < 6; ++b) sum_w += W_bar[(size_t)ch[c * 6 + b] * K + k];
                        out_root_qvals[k * 5 + 2 + c] = sum_w;
                    }
                }
            }
        }
    }
    for (int k = 0; k < K; ++k) out_bayes_vals[k] = W_bar[k];
}

void query_state_from_Lsub(
    const double* L0, const double* L1, const double* L2,
    const double* prior, const double* payoffs, double check_cost,
    int state_id, int depth,
    double* out_qvals, double* out_posterior
) {
    init_dp();
    int total_states = layer_start[MAX_DEPTH + 1];
    int nonterm_states = layer_start[MAX_DEPTH];

    static std::vector<double> W_single;
    if (W_single.size() < (size_t)total_states) W_single.resize(total_states);
    double* W_bar = W_single.data();

    #pragma omp parallel for schedule(static)
    for (int u = nonterm_states; u < total_states; ++u) {
        const int16_t* sids = &sub_ids[(size_t)u * 3];
        const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
        const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
        const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
        double A = 0.0;
        for (int s = 0; s < NUM_SEGMENTS; ++s) A += prior[s] * payoffs[s] * (l0[s] * l1[s] * l2[s]);
        W_bar[u] = (A > 0.0) ? A : 0.0;
    }

    for (int t = MAX_DEPTH - 1; t >= depth; --t) {
        int u_start = layer_start[t];
        int u_end = layer_start[t + 1];
        #pragma omp parallel for schedule(static)
        for (int u = u_start; u < u_end; ++u) {
            const int16_t* sids = &sub_ids[(size_t)u * 3];
            const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
            const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
            const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
            const int32_t* ch = &child_table[(size_t)u * NUM_OUTCOMES];
            double Z = 0.0, A = 0.0;
            for (int s = 0; s < NUM_SEGMENTS; ++s) {
                double q = prior[s] * (l0[s] * l1[s] * l2[s]);
                Z += q;
                A += q * payoffs[s];
            }
            double best = (A > 0.0) ? A : 0.0;
            for (int c = 0; c < 3; ++c) {
                double sum_w = -check_cost * Z;
                for (int b = 0; b < 6; ++b) sum_w += W_bar[ch[c * 6 + b]];
                if (sum_w > best) best = sum_w;
            }
            W_bar[u] = best;
        }
    }

    const int16_t* sids = &sub_ids[(size_t)state_id * 3];
    const double* l0 = &L0[(size_t)sids[0] * NUM_SEGMENTS];
    const double* l1 = &L1[(size_t)sids[1] * NUM_SEGMENTS];
    const double* l2 = &L2[(size_t)sids[2] * NUM_SEGMENTS];
    double Z = 0.0, A = 0.0;
    for (int s = 0; s < NUM_SEGMENTS; ++s) {
        double q = prior[s] * (l0[s] * l1[s] * l2[s]);
        out_posterior[s] = q;
        Z += q;
        A += q * payoffs[s];
    }
    if (Z > 0.0) {
        for (int s = 0; s < NUM_SEGMENTS; ++s) out_posterior[s] /= Z;
    }
    out_qvals[0] = 0.0;
    out_qvals[1] = (Z > 0.0) ? (A / Z) : -1e9;
    if (depth < MAX_DEPTH && Z > 0.0) {
        const int32_t* ch = &child_table[(size_t)state_id * NUM_OUTCOMES];
        for (int c = 0; c < 3; ++c) {
            double sum_w = -check_cost * Z;
            for (int b = 0; b < 6; ++b) sum_w += W_bar[ch[c * 6 + b]];
            out_qvals[2 + c] = sum_w / Z;
        }
    } else {
        out_qvals[2] = out_qvals[3] = out_qvals[4] = -1e9;
    }
}

// Fast 2-check (income + bank, 12 outcomes -> 125,970 states = 12.4x smaller!) batch solver for EVSI!
static bool init_2c = false;
static int layer2_start[MAX_DEPTH + 2];
static std::vector<int32_t> child2_table;
static std::vector<int16_t> sub2_ids;

static void ensure_2c() {
    if (init_2c) return;
    init_dp();
    layer2_start[0] = 0;
    for (int t = 0; t <= MAX_DEPTH; ++t) {
        layer2_start[t + 1] = layer2_start[t] + (int)binom(12 + t - 1, t);
    }
    int tot2 = layer2_start[MAX_DEPTH + 1];
    int nonterm2 = layer2_start[MAX_DEPTH];
    child2_table.resize((size_t)nonterm2 * 12);
    sub2_ids.resize((size_t)tot2 * 2);

    int cur[MAX_DEPTH + 1], nxt[MAX_DEPTH + 1];
    int b_sub[2][MAX_DEPTH + 1], len_sub[2];
    for (int t = 0; t <= MAX_DEPTH; ++t) {
        int sz = layer2_start[t + 1] - layer2_start[t];
        std::vector<int> tuples((size_t)sz * std::max(1, t));
        if (t > 0) generate_layer(12, t, 0, 0, cur, tuples);
        for (int r = 0; r < sz; ++r) {
            int u = layer2_start[t] + r;
            const int* tup = (t > 0) ? &tuples[(size_t)r * t] : nullptr;
            len_sub[0] = len_sub[1] = 0;
            for (int i = 0; i < t; ++i) {
                b_sub[tup[i] / 6][len_sub[tup[i] / 6]++] = tup[i] % 6;
            }
            for (int c = 0; c < 2; ++c) {
                int lt = len_sub[c];
                sub2_ids[(size_t)u * 2 + c] = (int16_t)((lt == 0) ? 0 : (sub_layer_start[lt] + colex_rank(b_sub[c], lt)));
            }
            if (t < MAX_DEPTH) {
                for (int d = 0; d < 12; ++d) {
                    int pos = 0;
                    while (pos < t && tup[pos] <= d) { nxt[pos] = tup[pos]; ++pos; }
                    nxt[pos] = d;
                    for (int i = pos; i < t; ++i) nxt[i + 1] = tup[i];
                    child2_table[(size_t)u * 12 + d] = layer2_start[t + 1] + colex_rank(nxt, t + 1);
                }
            }
        }
    }
    init_2c = true;
}

// Batch 2-check solver taking B pairs of (L1_task[3003,6], L2_task[3003,6]) -> ~2 seconds for 720 tasks!
void solve_2check_Lsub_batch(
    int B,
    const double* L1_batch, // shape (B, 3003, 6)
    const double* L2_batch, // shape (B, 3003, 6)
    int K, const double* priors, const double* payoffs, double check_cost,
    double* out_totals
) {
    ensure_2c();
    int tot2 = layer2_start[MAX_DEPTH + 1];     // 125,970
    int nonterm2 = layer2_start[MAX_DEPTH];     // 50,388
    size_t stride_L = (size_t)sub_layer_start[MAX_DEPTH + 1] * NUM_SEGMENTS;

    #pragma omp parallel
    {
        std::vector<double> W((size_t)tot2 * K); // Only 20 MB per thread!

        #pragma omp for schedule(static)
        for (int b_idx = 0; b_idx < B; ++b_idx) {
            const double* L1 = L1_batch + (size_t)b_idx * stride_L;
            const double* L2 = L2_batch + (size_t)b_idx * stride_L;

            for (int u = nonterm2; u < tot2; ++u) {
                const int16_t* sids = &sub2_ids[(size_t)u * 2];
                const double* l1 = &L1[(size_t)sids[0] * NUM_SEGMENTS];
                const double* l2 = &L2[(size_t)sids[1] * NUM_SEGMENTS];
                double* Wu = &W[(size_t)u * K];
                for (int k = 0; k < K; ++k) {
                    const double* pk = &priors[k * NUM_SEGMENTS];
                    double A = 0.0;
                    for (int s = 0; s < NUM_SEGMENTS; ++s) A += pk[s] * payoffs[s] * (l1[s] * l2[s]);
                    Wu[k] = (A > 0.0) ? A : 0.0;
                }
            }
            for (int u = nonterm2 - 1; u >= 0; --u) {
                const int16_t* sids = &sub2_ids[(size_t)u * 2];
                const double* l1 = &L1[(size_t)sids[0] * NUM_SEGMENTS];
                const double* l2 = &L2[(size_t)sids[1] * NUM_SEGMENTS];
                const int32_t* ch = &child2_table[(size_t)u * 12];
                double* Wu = &W[(size_t)u * K];
                for (int k = 0; k < K; ++k) {
                    const double* pk = &priors[k * NUM_SEGMENTS];
                    double Z = 0.0, A = 0.0;
                    for (int s = 0; s < NUM_SEGMENTS; ++s) {
                        double q = pk[s] * (l1[s] * l2[s]);
                        Z += q;
                        A += q * payoffs[s];
                    }
                    double best = (A > 0.0) ? A : 0.0;
                    for (int c = 0; c < 2; ++c) {
                        double sum_w = -check_cost * Z;
                        for (int b = 0; b < 6; ++b) sum_w += W[(size_t)ch[c * 6 + b] * K + k];
                        if (sum_w > best) best = sum_w;
                    }
                    Wu[k] = best;
                }
            }
            double tot = 0.0;
            for (int k = 0; k < K; ++k) tot += W[k];
            out_totals[b_idx] = tot;
        }
    }
}

}

